template:
// Pair with exact sum in a sorted array; returns indices or {-1,-1}.
pair<int,int> pairWithSum(const vector<int>& a, long long target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        long long s = (long long)a[lo] + a[hi];
        if (s == target) return {lo, hi};
        if (s < target) ++lo;          // a[lo] can't pair with anything left of hi to reach target
        else --hi;                     // a[hi] can't pair with anything right of lo without overshooting
    }
    return {-1, -1};
}

// Count pairs lo<hi with a[lo] + a[hi] <= k in a sorted array.
long long countPairsAtMost(const vector<int>& a, long long k) {
    long long cnt = 0;
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        if ((long long)a[lo] + a[hi] <= k) { cnt += hi - lo; ++lo; }  // all partners of lo up to hi fit
        else --hi;
    }
    return cnt;
}

// Same-direction (fast/slow): remove duplicates in place, returns new length.
int dedupInPlace(vector<int>& a) {
    if (a.empty()) return 0;
    int slow = 1;                                  // a[0..slow) is the kept, deduplicated prefix
    for (int fast = 1; fast < (int)a.size(); ++fast)
        if (a[fast] != a[slow - 1]) a[slow++] = a[fast];
    return slow;
}
